configFiles.template:
// Server name
hostname "${Hostname}"

// RCON password
rcon_password "${RconPassword}"

// Join password (empty = public)
sv_password "${PrivatePassword}"

// Internet server (0) or LAN only (1)
sv_lan 0

// Gameplay
mp_timelimit ${MapTimeLimit}
mp_friendlyfire ${FriendlyFire}
sv_realism ${Realism}
sv_hardcore_survival ${HardcoreSurvival}

// Map cycle (nmrih/cfg/mapcycle.txt)
mapcyclefile "mapcycle.txt"

// Server-side Steam Workshop maps (anonymous servers only, no GSLT token)
sv_workshop ${ServerWorkshop}
sv_workshop_autoupdate ${WorkshopAutoUpdate}

// Server logging
log on
sv_logbans 1
sv_logecho 1
sv_logfile 1

// Ban lists
exec banned_user.cfg
exec banned_ip.cfg

