//refAssemblies: System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = (string)ThisService.RootDirectory;

// srcds writes steam_appid.txt next to itself only during its first run, which therefore starts without Steam.
// Writing it before every start makes the first start work too.
var appIdFile = Path.Combine(root, "steam_appid.txt");
if (!File.Exists(appIdFile) || File.ReadAllText(appIdFile).Trim('\0', '\r', '\n', ' ') != "224260")
{
    File.WriteAllText(appIdFile, "224260\n");
    // Scripts run as root on Linux: give the file to the service user (owner of the service root).
    if (System.OperatingSystem.IsLinux()) Globals.OperatingSystem.SetFileOwnerAutoDetect(appIdFile);
    ScriptConsole.WriteLine((object)"Wrote steam_appid.txt (224260).");
}

// -condebug appends to console.log forever; keep only the previous run next to the new one.
var log = Path.Combine(root, "nmrih", "console.log");
if (File.Exists(log))
{
    File.Move(log, Path.Combine(Path.GetDirectoryName(log), "console.previous.log"), true);
}

if (System.OperatingSystem.IsLinux())
{
    // The Steam download does not keep the exec bit.
    foreach (var name in new[] { "srcds_run", "srcds_linux" })
    {
        var path = Path.Combine(root, name);
        if (!File.Exists(path)) continue;
        var mode = File.GetUnixFileMode(path);
        var wanted = mode | UnixFileMode.UserExecute | UnixFileMode.GroupExecute | UnixFileMode.OtherExecute;
        if (mode != wanted) { File.SetUnixFileMode(path, wanted); ScriptConsole.WriteLine((object)("Made " + name + " executable.")); }
    }

    // srcds_linux is a 32-bit program: install the 32-bit system libraries it and the engine need when the host
    // lacks them (Debian/Ubuntu: apt-get, Red Hat: dnf or yum).
    var packages = new Dictionary<string, (string[] Apt, string[] Rpm)>
    {
        ["ld-linux.so.2"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libc.so.6"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libm.so.6"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libdl.so.2"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libpthread.so.0"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["librt.so.1"] = (new[] { "libc6-i386" }, new[] { "glibc.i686" }),
        ["libgcc_s.so.1"] = (new[] { "lib32gcc-s1", "lib32gcc1" }, new[] { "libgcc.i686" }),
        ["libstdc++.so.6"] = (new[] { "lib32stdc++6" }, new[] { "libstdc++.i686" }),
        ["libz.so.1"] = (new[] { "lib32z1" }, new[] { "zlib.i686" }),
    };
    var missing = new List<string>();
    if (!File.Exists("/lib/ld-linux.so.2")) missing.Add("ld-linux.so.2");
    else
    {
        var bin = Path.Combine(root, "bin");
        foreach (var file in new[] { Path.Combine(root, "srcds_linux"), Path.Combine(bin, "dedicated_srv.so"), Path.Combine(bin, "engine_srv.so"),
                                     Path.Combine(root, "nmrih", "bin", "server_srv.so") })
        {
            if (!File.Exists(file)) continue;
            Shell("LD_LIBRARY_PATH='" + root + ":" + bin + "' ldd '" + file + "'", out var lddOutput);
            missing.AddRange(lddOutput.Split('\n').Where(l => l.Contains("=> not found")).Select(l => l.Trim().Split(' ')[0]));
        }
    }
    foreach (var soname in missing.Distinct())
    {
        if (!packages.TryGetValue(soname, out var candidates))
        {
            ScriptConsole.WriteLine((object)("The server needs " + soname + ", which is not installed on this host."));
            continue;
        }
        ScriptConsole.WriteLine((object)(soname + " (32-bit) is missing on this host; installing it."));
        var apt = Shell("command -v apt-get", out _);
        string tool;
        if (apt)
        {
            Shell("dpkg --print-foreign-architectures | grep -q i386 || dpkg --add-architecture i386", out _);
            tool = "DEBIAN_FRONTEND=noninteractive apt-get install -y ";
        }
        else tool = Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
        var names = apt ? candidates.Apt : candidates.Rpm;
        var installed = names.Any(p => Shell(tool + p, out _));
        if (!installed && apt && Shell("apt-get update", out _)) installed = names.Any(p => Shell(tool + p, out _));
        if (!installed) throw new Exception(soname + " (32-bit) is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
        ScriptConsole.WriteLine((object)("Installed " + soname + "."));
    }
}

bool Shell(string command, out string output)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", command }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

