using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// No More Room in Hell servers run Workshop MAPS themselves (sv_workshop 1): the maps listed in
// nmrih/workshop_maps.txt are updated when the server starts, players who join get them from the Workshop, and
// the server's Steam client keeps them in workshop/content/224260/<id>. The panel downloaded this item to learn its
// map name; move it to where the server keeps it, add it to the list and the map cycle, and tell a running server.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string downloaded = Convert.ToString(Dynamic.InstallPath);

var maps = FindMaps(downloaded);
if (maps.Count == 0) maps = FindMaps(ServerItemDir(fileId));
if (maps.Count == 0)
{
    // Like the server's own workshop_download_collection: a non-map item (skin, sound, ...) is ignored, so a
    // collection that mixes maps and other add-ons still installs its maps.
    try { if (Directory.Exists(downloaded)) Directory.Delete(downloaded, true); } catch { }
    ScriptConsole.WriteLine((object)("Workshop item " + fileId + " contains no map (.bsp) and was ignored. No More Room in Hell servers load Workshop maps only; skins, sounds and other add-ons are installed by the players."));
    return;
}

// Keep one copy, where the server's own Workshop client looks for it.
var target = ServerItemDir(fileId);
if (Directory.Exists(downloaded) && !string.Equals(Path.GetFullPath(downloaded), Path.GetFullPath(target), StringComparison.Ordinal))
{
    if (Directory.Exists(target)) Directory.Delete(target, true);
    Directory.CreateDirectory(Path.GetDirectoryName(target));
    Directory.Move(downloaded, target);
}
GiveToServiceUser(Path.Combine(Root(), "workshop"), true);

var list = ReadMaps();
var cycle = ReadCycle();
foreach (var map in maps)
{
    list.RemoveAll(kv => kv.Key.Equals(map, StringComparison.OrdinalIgnoreCase));
    list.Add(new KeyValuePair<string, string>(map, fileId));
    if (!cycle.Any(m => m.Equals(map, StringComparison.OrdinalIgnoreCase))) cycle.Add(map);
    ScriptConsole.WriteLine((object)("Added Workshop map " + map + " (" + fileId + ") to workshop_maps.txt and mapcycle.txt."));
}
WriteMaps(list);
WriteCycle(cycle);

// A running server keeps its list in memory: let it download and register the map now.
if (await SendToServer("workshop_download " + fileId))
    ScriptConsole.WriteLine((object)("Sent workshop_download " + fileId + " to the server. Change to the map with: changelevel " + maps[0]));
else
    ScriptConsole.WriteLine((object)"The server is not running; it loads the map list the next time it starts.");

// --- Shared helpers: the server's own Workshop map list (nmrih/workshop_maps.txt) and the map cycle. ---
string Root() => (string)ThisService.RootDirectory;
string MapsFile() => Path.Combine(Root(), "nmrih", "workshop_maps.txt");
string CycleFile() => Path.Combine(Root(), "nmrih", "cfg", "mapcycle.txt");
string ServerItemDir(string id) => Path.Combine(Root(), "workshop", "content", "224260", id);

// workshop_maps.txt is a KeyValues file: "WorkshopMaps" { "<map name>" "<workshop id>" ... }
List<KeyValuePair<string, string>> ReadMaps()
{
    var list = new List<KeyValuePair<string, string>>();
    if (!File.Exists(MapsFile())) return list;
    foreach (Match m in Regex.Matches(File.ReadAllText(MapsFile()), "\"([^\"]+)\"\\s+\"([0-9]+)\""))
        list.Add(new KeyValuePair<string, string>(m.Groups[1].Value, m.Groups[2].Value));
    return list;
}

void WriteMaps(List<KeyValuePair<string, string>> list)
{
    var sb = new StringBuilder("\"WorkshopMaps\"\n{\n");
    foreach (var kv in list) sb.Append("\t\"" + kv.Key + "\"\t\t\"" + kv.Value + "\"\n");
    sb.Append("}\n");
    File.WriteAllText(MapsFile(), sb.ToString());
    GiveToServiceUser(MapsFile(), false);
}

List<string> ReadCycle() => File.Exists(CycleFile())
    ? File.ReadAllLines(CycleFile()).Select(l => l.Trim()).Where(l => l != "").ToList()
    : new List<string>();

void WriteCycle(List<string> maps)
{
    File.WriteAllText(CycleFile(), string.Join("\n", maps) + "\n");
    GiveToServiceUser(CycleFile(), false);
}

// Scripts run as root on Linux: files they create must belong to the service user (the owner of the service root).
void GiveToServiceUser(string path, bool directory)
{
    if (!System.OperatingSystem.IsLinux()) return;
    if (directory) Globals.OperatingSystem.SetDirectoryOwnerAutoDetect(path, true);
    else Globals.OperatingSystem.SetFileOwnerAutoDetect(path);
}

async Task<bool> SendToServer(string command)
{
    try
    {
        await ServiceManagerService.SendConsoleInput(ThisService.ServiceId, command);
        return true;
    }
    catch
    {
        return false;
    }
}

// Map names (maps/<name>.bsp) of a Workshop item: loose .bsp files or .bsp entries inside a .vpk.
List<string> FindMaps(string dir)
{
    var names = new List<string>();
    if (!Directory.Exists(dir)) return names;
    foreach (var f in Directory.GetFiles(dir, "*.bsp", SearchOption.AllDirectories))
        names.Add(Path.GetFileNameWithoutExtension(f));
    foreach (var f in Directory.GetFiles(dir, "*.vpk", SearchOption.AllDirectories))
    {
        if (Regex.IsMatch(Path.GetFileName(f), "_[0-9]{3}\\.vpk$")) continue; // data chunks of a multi-file vpk
        try { names.AddRange(VpkMaps(f)); } catch { }
    }
    return names.Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
}

List<string> VpkMaps(string file)
{
    var maps = new List<string>();
    using (var r = new BinaryReader(File.OpenRead(file)))
    {
        if (r.ReadUInt32() != 0x55aa1234) return maps;
        var version = r.ReadUInt32();
        r.ReadUInt32(); // tree size
        if (version == 2) { r.ReadUInt32(); r.ReadUInt32(); r.ReadUInt32(); r.ReadUInt32(); }
        string Str() { var b = new List<byte>(); byte c; while ((c = r.ReadByte()) != 0) b.Add(c); return Encoding.UTF8.GetString(b.ToArray()); }
        while (true)
        {
            var ext = Str(); if (ext == "") break;
            while (true)
            {
                var path = Str(); if (path == "") break;
                while (true)
                {
                    var name = Str(); if (name == "") break;
                    r.ReadUInt32(); var preload = r.ReadUInt16(); r.ReadUInt16(); r.ReadUInt32(); r.ReadUInt32(); r.ReadUInt16();
                    if (preload > 0) r.ReadBytes(preload);
                    if (ext.Equals("bsp", StringComparison.OrdinalIgnoreCase) && path.Trim('/').Equals("maps", StringComparison.OrdinalIgnoreCase)) maps.Add(name);
                }
            }
        }
    }
    return maps;
}
// --- end of shared helpers ---

