using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Removes the Workshop map(s) of this item from nmrih/workshop_maps.txt and the map cycle, deletes the server's
// copy in workshop/content/224260/<id> and tells a running server (workshop_remove <map>).
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);

var list = ReadMaps();
var maps = list.Where(kv => kv.Value == fileId).Select(kv => kv.Key).ToList();
maps.AddRange(FindMaps(ServerItemDir(fileId)).Where(m => !maps.Contains(m, StringComparer.OrdinalIgnoreCase)));

foreach (var map in maps)
{
    if (await SendToServer("workshop_remove " + map)) ScriptConsole.WriteLine((object)("Sent workshop_remove " + map + " to the server."));
}
// The server rewrites workshop_maps.txt after workshop_remove; give it a moment before writing our version.
await Task.Delay(2000);

list = ReadMaps();
list.RemoveAll(kv => kv.Value == fileId || maps.Contains(kv.Key, StringComparer.OrdinalIgnoreCase));
WriteMaps(list);

var cycle = ReadCycle();
if (cycle.RemoveAll(m => maps.Contains(m, StringComparer.OrdinalIgnoreCase)) > 0) WriteCycle(cycle);

if (Directory.Exists(ServerItemDir(fileId))) Directory.Delete(ServerItemDir(fileId), true);
ScriptConsole.WriteLine((object)(maps.Count == 0
    ? "Workshop item " + fileId + " was not in workshop_maps.txt."
    : "Removed Workshop map " + string.Join(", ", maps) + " (" + fileId + ")."));

